// === Tab: mySketch ===
/**
Author: qp91mn64

Particle Blurred

Particles follow a line that follows the mouse.
Low alpha for blurred effect with trails.

Move the mouse to move the line
`s`/`S`: Save an image
`r`/`R`: Clear the canvas

See also
My sketch Particle Blurred 2: Invisible Line: https://openprocessing.org/@u594485/2989165
*/
let x = [];
let y = [];
let v = [];
let particleCount = 500;
let lineX, lineV;
let dt = 1;
let k;
function setup() {
    createCanvas(windowWidth, windowHeight);
    background(0);
    k = windowWidth / 600;
    for (let i = 0; i < particleCount; i++) {
        x.push(Math.random() * width);
        y.push(Math.random() * height);
        v.push(0);
    }
    lineX = windowWidth / 2;
}
function draw() {
    background(0, 1);  // Each frame the canvas gets a little darker?
    let n = 0;
    lineV = constrain(- (lineX - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * 0.005, -0.9 * k, 0.9 * k);
    lineX += lineV * dt;
    if (lineX > width) {lineX = width;} else if (lineX < 0) {lineX = 0;}
    for (let i = 0; i < particleCount; i++) {
        v[i] = constrain(-(x[i] - lineX) * 0.005, -0.9 * k, 0.9 * k);
        x[i] += v[i] * dt;
        // When close enough, particles disappear and reappear at the edge of the canvas randomly
        // Math.random() used, in case they converge into vertical lines and no longer scatter
        // Besides, when particles gather together, the line in motion don't clear all of them
        // So that they will be on the other side.
        if (n < 3 && (abs(x[i] - lineX) < 15 * k * Math.random() && Math.random() < 0.01 || abs(x[i] - lineX) < k)) {
            n++;
            y[i] = Math.random() * height;
            if (x[i] > lineX) {
                x[i] = width + 1;
            } else {
                x[i] = -1;
            }
        }
    }
    display();
}
function display() {
    let v1 = map(lineV, 1, -1, 0, 255);
    stroke(0, v1, 223, 15);
    line(lineX, 0, lineX, height);
    noStroke();
    for (let i = 0; i < particleCount; i++) {
        let v2 = map(v[i], -1, 1, 0, 255);
        fill(0, v2, noise(i) * 255, 3);  // Alpha is low, so that the graphics looks blurred with traces
        circle(x[i], y[i], noise(i + 0.2) * 5 + 1);
    }
}
function keyPressed() {
    if (key == "s" || key == "S") {
        save1();
    }
    if (key == "r" || key == "R") {
        background(0);
    }
}
function save1() {
    let stamp = year() + nf(month(), 2) + nf(day(), 2) + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + `_${millis()}_${random(10000)|0}`;
    let imageName = "Particle Blurred " + "s" + stamp;
    saveCanvas(imageName);
}

